import unittest
from unittest.mock import patch
import game

class TestGameFunctions(unittest.TestCase):

    @patch('builtins.input', side_effect=['abc', '0', '101', '50'])
    def test_get_user_guess_invalid_input(self, mock_input):
        with self.assertRaises(ValueError):
            game.get_user_guess()

    @patch('builtins.input', side_effect=['101', '50'])
    def test_get_user_guess_out_of_range(self, mock_input):
        self.assertEqual(game.get_user_guess(), 50)

    @patch('builtins.input', side_effect=['50'])
    def test_get_user_guess_valid_input(self, mock_input):
        self.assertEqual(game.get_user_guess(), 50)

    @patch('builtins.print')
    @patch('builtins.input', side_effect=['50'])
    def test_play_game_guess_correct(self, mock_input, mock_print):
        game.play_game()
        mock_print.assert_called_with("Congratulations! You guessed the number in 1 attempts!")

    @patch('builtins.print')
    @patch('builtins.input', side_effect=['25', '75'])

